const body = $input.first().json.body;
const safe = (value) => typeof value === 'string' && /^[A-Za-z0-9][A-Za-z0-9._-]{0,199}$/.test(value);
const r1 = body?.fq1?.[0]?.name;
const r2 = body?.fq2?.[0]?.name;
const bed = body?.bedFile?.[0]?.name;
if (!safe(body?.ornekAdi) || !safe(r1) || !safe(r2) || r1 === r2 ||
    (bed != null && !safe(bed)) || !/^(?:[1-9]|[12][0-9]|3[0-2])$/.test(String(body?.ncore))) {
  throw new Error('Invalid sample name, input file name or core count');
}
return $input.all();
